import math
from collections import defaultdict

def calculate_list_of_primes(n):
	primes = []
	isprime = []
	for i in range(0, n + 1):
		isprime.append(True)
	for i in range(2, math.floor(math.sqrt(n)) + 1):
		if isprime[i] == True:
			for j in range(i ** 2, n + 1, i):
				isprime[j] = False
	for i in range(2, n):
		if isprime[i] == True:
			primes.append(i)
	return primes
prime_list = calculate_list_of_primes(600)

def calculate_euler_totient(n):
	totient = n
	for i in prime_list:
		if n % i == 0:
			totient = totient * (i - 1) // i
	return totient

def necklace_count(n, k):
	count = 0
	for i in range(1, n + 1):
		if n % i == 0:
			count = count + calculate_euler_totient(i) * k ** (n // i)
	count = count // n
	return count

def bracelet_count(n, k):
	count = necklace_count(n, k)
	if n % 2 == 0:
		count = count + (k + 1) * k ** (n // 2) // 2
	else:
		count = count + k ** ((n + 1) // 2)
	return count // 2

def modified_manacher(str):
	odd = [0]
	radius = []
	for i in range(1, len(str) + 2):
		radius.append(0)
	n = 0
	i = 1
	text = '$'
	delta = 0
	for c in str:
		s = i - radius[i] + delta
		text += c
		while i + radius[i] <= n:
			radius[i] = min(radius[s + n - i - delta], n - i)
			if i + radius[i] == n and text[i - radius[i] - 1 + delta] == c:
				radius[i] = radius[i] + 1
				break
			i = i + 1
		n = n + 1
		odd.append(2 * radius[i] + 1 - delta)
	even = [0]
	radius = []
	for i in range(1, len(str) + 2):
		radius.append(0)
	n = 0
	i = 1
	text = '$'
	delta = 1
	for c in str:
		s = i - radius[i] + delta
		text += c
		while i + radius[i] <= n:
			radius[i] = min(radius[s + n - i - delta], n - i)
			if i + radius[i] == n and text[i - radius[i] - 1 + delta] == c:
				radius[i] = radius[i] + 1
				break
			i = i + 1
		n = n + 1
		even.append(2 * radius[i] + 1 - delta)
	even_odd = []
	for i in range(0, len(even)):
		even_odd.append(max(even[i], odd[i]))
	left = []
	right = []
	for i in range(1, len(even)):
		left.append(i - even_odd[i])
		right.append(i - 1)
	d = defaultdict(list)
	for i in range(0, len(left)):
		d[right[i] - left[i] + 1].append([left[i], right[i]])
	counts = set()
	answer = 0
	for (key, value) in d.items():
		if len(value) > 1:
			for i in value:
				counts.add(hash(str[i[0]:i[1] + 1]))
		else:
			answer += 1
	answer += len(counts)
	return answer
